import io
import unittest

def run_case(case_class):
    suite = unittest.TestLoader().loadTestsFromTestCase(case_class)
    output = io.StringIO()
    runner = unittest.TextTestRunner(stream=output, verbosity=0)
    result = runner.run(suite)
    return (result.testsRun, result.wasSuccessful())

class __PassingCase(unittest.TestCase):
    def test_sum(self):
        self.assertEqual(1 + 1, 2)
class __FailingCase(unittest.TestCase):
    def test_sum(self):
        self.assertEqual(1 + 1, 3)
class __EmptyCase(unittest.TestCase):
    pass
class __TwoCases(unittest.TestCase):
    def test_a(self):
        self.assertEqual(2 * 2, 4)
    def test_b(self):
        self.assertEqual(3 - 1, 2)
